  - { icon: "lucide:target", title: Mission, items: ["Konkreter Fokus für einen begrenzten Zeitraum", "Was tun wir als Nächstes – und wie?"] }
  - { icon: "lucide:heart", title: Werte, items: ["Was ist uns grundsätzlich wichtig?", "Was steht über kurzfristigen wirtschaftlichen Interessen?"] }
